Use ASP.NET Core's `WebApplicationFactory<T>` to host your server in-process and drive MCP requests through its `HttpClient`:

```csharp
// MyMcpServerTests.cs
using Microsoft.AspNetCore.Mvc.Testing;
using System.Net.Http.Json;
using System.Text.Json;

public class McpServerTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpServerTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2025-03-26",
            body.GetProperty("result").GetProperty("protocolVersion").GetString());
    }

    [Fact]
    public async Task ToolsList_ReturnsRegisteredTools()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 2,
            method = "tools/list",
            @params = new { }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        var tools = body.GetProperty("result").GetProperty("tools");
        Assert.True(tools.GetArrayLength() > 0);
    }
}
```

**Key points:**

1. **`WebApplicationFactory<Program>`** boots your app in-memory — no ports, no real network.
2. **`CreateClient()`** gives you an `HttpClient` wired to the test server's pipeline.
3. Send standard JSON-RPC 2.0 payloads to your MCP endpoint (adjust `/mcp` to your route).
4. For **Streamable HTTP** (SSE responses), use `HttpCompletionOption.ResponseHeadersRead` and read the stream line-by-line.

**For SSE/streaming responses:**

```csharp
var req = new HttpRequestMessage(HttpMethod.Post, "/mcp")
{
    Content = JsonContent.Create(toolCallRequest)
};
req.Headers.Accept.Add(new("text/event-stream"));

var response = await _client.SendAsync(req,
    HttpCompletionOption.ResponseHeadersRead);

using var stream = await response.Content.ReadAsStreamAsync();
using var reader = new StreamReader(stream);

while (await reader.ReadLineAsync() is { } line)
{
    if (line.StartsWith("data: "))
    {
        var evt = JsonSerializer.Deserialize<JsonElement>(line[6..]);
        // assert on streamed events
    }
}
```

**To mock dependencies**, override services in the factory:

```csharp
var factory = new WebApplicationFactory<Program>()
    .WithWebHostBuilder(builder =>
    {
        builder.ConfigureServices(services =>
        {
            services.AddSingleton<IMyService>(new FakeService());
        });
    });
```

This gives you full protocol-level coverage (headers, status codes, JSON-RPC framing) without any network overhead.
